        "\"السعودية تحمي اليمن.\" \"السعودية طرف في الحرب، لا منقذ من الخارج. ضرباتها قتلت مدنيين؛ وإغلاق حدودها ودعمها لجماعات مسلحة شكّلا الاقتصاد. وهي تستضيف أيضاً ملايين العمال اليمنيين وقد موّلت الرواتب. كلا الأمرين صحيح.\"",
        "\"إيران وراء كل ذلك.\" \"تدعم إيران Houthis، وذلك مهم. لا يفسّر ذلك أزمة الرواتب، ولا المؤسسات المنقسمة، ولا أزمة المياه، ولا انهيار المساعدات — فتلك قرارات يمنية وإقليمية أيضاً.\"",
