        "\"انتهت حرب سوريا. لم تنتهِ طوارئها. يحتاج 15.6 مليون شخص إلى المساعدة؛ ولم يُموَّل سوى 16% من خطة 2026. OCHA, 14 Apr 2026; IRC, 11 May 2026.\"",
