        "صدمات مناخية وجفاف. لم تحسّن محاصيل 2026 الجيدة إمكانية الحصول؛ البطالة، لا إمدادات الغذاء، هي القيد الملزم. (IPC; World Bank.)",
        "عودة جماعية. نمو السكان بنسبة 11 في المئة في 2025، المدفوع بالعودة، تجاوز اقتصاداً راكداً معتمداً على المساعدات. (World Bank; OCHA.)",
        "انهيار المساعدات. النداء مموَّل بنحو الربع بينما ترتفع الاحتياجات. (OCHA.)",
        "حظر النوع الاجتماعي. استبعاد النساء من التعليم والعمل يقلّص القوى العاملة في الصحة والتعليم ويمنع وصول المساعدات إلى النساء. (OCHA; CARE.)",
        "حظر الأفيون. دمّر هذا الحظر الدخل النقدي الريفي من دون بديل، فزاد الدين والبيوع الاضطرارية. (UNODC; World Bank.)",
        "إغلاق الحدود والحرب الإقليمية. نزاع إيران/هرمز وإغلاقات حدود باكستان يرفعان الأسعار ويعطّلان التجارة. (World Bank; تفسير.)"
