        "ادعم منظمة صحية تقودها امرأة. العاملات الصحيات هن السبيل الوحيد إلى كثير من النساء. موّل عيادات توظّف النساء وتحمي سلامتهن. الوقت: 30 دقيقة.",
        "اكتب عن فجوة التمويل، وليس عن الحظر فقط. الحظر حقيقي؛ وخفض التمويل حقيقي أيضاً وقاتل على الفور. اطلب من ممثلك استعادة التمويل الإنساني والإبقاء على الاستثناءات الإنسانية في العقوبات وقواعد العمل المصرفي. الوقت: 30 دقيقة.",
