        "\"لا تعترف بـ Taliban.\" \"الاعتراف مسألة منفصلة عن المساعدات الإنسانية. يمكنك رفض الاعتراف ومع ذلك تمويل الغذاء والصحة وتعليم الفتيات. ربط الاثنين يعاقب المدنيين على جرائم النظام.\"",
