        "\"السعودية لم تلغِ kafala. الإقامة ما زالت مرتبطة بكفيل؛ تصاريح الخروج ما زالت موجودة؛ العاملات المنزليات ما زلن خارج نظام العمل. Migrant-Rights.org, 3 Apr 2026; HRW, Jan 2026.\"",
