        "\"لماذا توجد طوائف؟\" للأسباب نفسها كما في تقاليد أخرى: التاريخ، والسياسة، واللاهوت، والتفسير. [CITED FACT]",
        "\"هل يمكنني قراءة القرآن؟\" نعم. استخدم ترجمة موثوقة ودليلاً؛ اسأل صديقاً مسلماً عما يعنيه المقطع في سياقه. [REASONED GUIDANCE]"
